import { getCustomer, TIER_DISCOUNTS, normalizeId } from './customers.js';
import { getProduct } from './catalogue.js';
import { ok, fail } from './result.js';
import { nextInvoiceNumber } from './numbering.js';
import { roundCents } from './money.js';

/**
 * Validate discount is a number from 0 to 100.
 * @param {unknown} discount
 * @returns {{ ok: true } | { ok: false, error: string }}
 */
function validateDiscount(discount) {
  if (discount === undefined || discount === null) return { ok: true };
  if (typeof discount !== 'number' || discount < 0 || discount > 100) return { ok: false, error: 'DISCOUNT_INVALID' };
  return { ok: true };
}

/**
 * Create a new draft invoice.
 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number, discountPercent?: number }> }}
 * @returns {{ ok: true, value: object } | { ok: false, error: string }}
 */
export function createInvoice({ customerId, issueDate, lines }) {
  // Normalize customer ID
  const normalizedCustomerId = normalizeId(customerId);

  // Validate customer exists
  const customer = getCustomer(normalizedCustomerId);
  if (!customer.ok) return customer;

  // Validate issueDate is in YYYY-MM-DD format and is a real date
  if (!/^\d{4}-\d{2}-\d{2}$/.test(issueDate ?? '')) return fail('DATE_INVALID');
  const [year, month, day] = issueDate.split('-').map(Number);
  const date = new Date(year, month - 1, day);
  if (date.getFullYear() !== year || date.getMonth() + 1 !== month || date.getDate() !== day) {
    return fail('DATE_INVALID');
  }

  // Validate lines is a non-empty array
  if (!Array.isArray(lines) || lines.length === 0) return fail('NO_LINES');

  // Validate and enrich each line
  const enrichedLines = [];
  for (const line of lines) {
    // Validate qty is a positive integer
    if (!Number.isInteger(line.qty) || line.qty <= 0) return fail('QTY_INVALID');

    // Validate discount
    const discountValidation = validateDiscount(line.discountPercent);
    if (!discountValidation.ok) return fail(discountValidation.error);

    // Get product and enrich line
    const product = getProduct(line.sku);
    if (!product.ok) return product;

    const enrichedLine = {
      sku: line.sku,
      name: product.value.name,
      qty: line.qty,
      unitPrice: product.value.unitPrice,
      vatRate: product.value.vatRate,
    };

    // Apply discount: line's own discount wins, otherwise use customer tier discount
    if (line.discountPercent !== undefined && line.discountPercent !== null) {
      enrichedLine.discountPercent = line.discountPercent;
    } else {
      const tierDiscount = TIER_DISCOUNTS[customer.value.tier];
      if (tierDiscount > 0) {
        enrichedLine.discountPercent = tierDiscount;
      }
    }

    enrichedLines.push(enrichedLine);
  }

  const invoice = {
    customerId: normalizedCustomerId,
    issueDate,
    status: 'draft',
    lines: enrichedLines,
  };

  return ok(invoice);
}

/**
 * Calculate the total amount for a line (qty × unitPrice).
 * @param {{ qty: number, unitPrice: number }}
 * @returns {{ ok: true, value: number } | { ok: false, error: string }}
 */
export function lineTotal(line) {
  if (!line || !Number.isInteger(line.qty) || line.qty <= 0) return fail('QTY_INVALID');
  if (!Number.isInteger(line.unitPrice) || line.unitPrice < 0) return fail('AMOUNT_INVALID');
  return ok(line.qty * line.unitPrice);
}

/**
 * Calculate subtotal, discount, VAT and total for an invoice.
 * @param {{ lines: Array<{ qty: number, unitPrice: number, discountPercent?: number, vatRate: number }> }}
 * @returns {{ ok: true, value: { subtotal: number, discount: number, vat: number, total: number } } | { ok: false, error: string }}
 */
export function invoiceTotals(invoice) {
  if (!invoice || !Array.isArray(invoice.lines) || invoice.lines.length === 0) return fail('NO_LINES');

  let subtotal = 0;
  let totalDiscount = 0;
  let totalVat = 0;

  for (const line of invoice.lines) {
    const lt = lineTotal(line);
    if (!lt.ok) return lt;
    subtotal += lt.value;

    let lineDiscount = 0;
    if (line.discountPercent !== undefined && line.discountPercent !== null) {
      lineDiscount = Math.max(0, line.discountPercent / 100 * lt.value);
      totalDiscount += lineDiscount;
    }

    const discountedAmount = Math.max(0, lt.value - lineDiscount);
    if (line.vatRate && line.vatRate > 0) {
      const lineVat = roundCents(discountedAmount * (line.vatRate / 100));
      totalVat += Math.max(0, lineVat);
    }
  }

  const total = Math.max(0, subtotal - totalDiscount + totalVat);
  return ok({ subtotal, discount: Math.max(0, totalDiscount), vat: Math.max(0, totalVat), total });
}

/**
 * Add or increment a line on a draft invoice.
 * @param {object} invoice
 * @param {{ sku: string, qty: number, discountPercent?: number }}
 * @returns {{ ok: true, value: object } | { ok: false, error: string }}
 */
export function addLine(invoice, { sku, qty, discountPercent }) {
  // Validate invoice is draft
  if (!invoice || invoice.status !== 'draft') return fail('NOT_DRAFT');

  // Validate qty
  if (!Number.isInteger(qty) || qty <= 0) return fail('QTY_INVALID');

  // Validate discount
  const discountValidation = validateDiscount(discountPercent);
  if (!discountValidation.ok) return fail(discountValidation.error);

  // Get product
  const product = getProduct(sku);
  if (!product.ok) return product;

  // Get customer to determine tier discount
  const customer = getCustomer(invoice.customerId);
  if (!customer.ok) return customer;

  // Check if line with this SKU already exists
  const existingLine = invoice.lines.find((l) => l.sku === sku);
  const newLine = {
    sku,
    name: product.value.name,
    qty,
    unitPrice: product.value.unitPrice,
    vatRate: product.value.vatRate,
  };

  // Apply discount: line's own discount wins, otherwise use customer tier discount
  if (discountPercent !== undefined && discountPercent !== null) {
    newLine.discountPercent = discountPercent;
  } else {
    const tierDiscount = TIER_DISCOUNTS[customer.value.tier];
    if (tierDiscount > 0) {
      newLine.discountPercent = tierDiscount;
    }
  }

  const newLines = existingLine
    ? invoice.lines.map((l) =>
        l.sku === sku
          ? {
              ...l,
              qty: l.qty + qty,
            }
          : l
      )
    : [...invoice.lines, newLine];

  return ok({
    ...invoice,
    lines: newLines,
  });
}

/**
 * Remove a line from a draft invoice.
 * @param {object} invoice
 * @param {string} sku
 * @returns {{ ok: true, value: object } | { ok: false, error: string }}
 */
export function removeLine(invoice, sku) {
  // Validate invoice is draft
  if (!invoice || invoice.status !== 'draft') return fail('NOT_DRAFT');

  // Find the line
  const lineIndex = invoice.lines.findIndex((l) => l.sku === sku);
  if (lineIndex === -1) return fail('LINE_NOT_FOUND');

  // Check if this is the last line
  if (invoice.lines.length === 1) return fail('NO_LINES');

  // Remove the line
  const newLines = invoice.lines.filter((l) => l.sku !== sku);

  return ok({
    ...invoice,
    lines: newLines,
  });
}

/**
 * Issue a draft invoice, assigning it a number and changing status to 'issued'.
 * @param {object} invoice
 * @param {Array<string>} existingNumbers
 * @returns {{ ok: true, value: object } | { ok: false, error: string }}
 */
export function issueInvoice(invoice, existingNumbers) {
  // Validate invoice is draft
  if (!invoice || invoice.status !== 'draft') return fail('NOT_DRAFT');

  // Get next invoice number
  const numberResult = nextInvoiceNumber(existingNumbers, invoice.issueDate);
  if (!numberResult.ok) return numberResult;

  const newInvoice = {
    ...invoice,
    number: numberResult.value,
    status: 'issued',
  };

  return ok(newInvoice);
}

