/**
 * Check if a text is a valid date in YYYY-MM-DD format.
 * @param {string} text
 * @returns {boolean}
 */
export function isValidDate(text) {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(text ?? '')) return false;
  const [year, month, day] = text.split('-').map(Number);
  const date = new Date(Date.UTC(year, month - 1, day));
  return date.getUTCFullYear() === year && date.getUTCMonth() + 1 === month && date.getUTCDate() === day;
}

/**
 * Add n days to a date (YYYY-MM-DD string), all in UTC.
 * @param {string} date
 * @param {number} n
 * @returns {string}
 */
export function addDays(date, n) {
  const [year, month, day] = date.split('-').map(Number);
  const d = new Date(Date.UTC(year, month - 1, day));
  d.setUTCDate(d.getUTCDate() + n);
  const y = d.getUTCFullYear();
  const m = String(d.getUTCMonth() + 1).padStart(2, '0');
  const dy = String(d.getUTCDate()).padStart(2, '0');
  return `${y}-${m}-${dy}`;
}

/**
 * Calculate days between two dates (b minus a), in whole days, all in UTC.
 * @param {string} a
 * @param {string} b
 * @returns {number}
 */
export function daysBetween(a, b) {
  const [ay, am, ad] = a.split('-').map(Number);
  const [by, bm, bd] = b.split('-').map(Number);
  const dateA = new Date(Date.UTC(ay, am - 1, ad));
  const dateB = new Date(Date.UTC(by, bm - 1, bd));
  const diffMs = dateB - dateA;
  return Math.floor(diffMs / (1000 * 60 * 60 * 24));
}

